{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_text",
        "hero_image",
        "intro_text",
        "section_heading_stack",
        "router_card",
        "pi_config_card",
        "quick_actions_title",
        "quick_actions_stack_buttons",
        "sources_title",
        "sources_stack_buttons"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Static IP Configuration for Raspberry Pi",
        "variant": "h1"
      },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Raspberry_Pi_4_Model_B_-_Side.jpg/1200px-Raspberry_Pi_4_Model_B_-_Side.jpg"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "To ensure your Raspberry Pi 4 always receives 192.168.1.50, you should implement 'Address Reservation' on the router first, then optionally configure the Pi's internal settings for redundancy."
      },
      "children": []
    },
    "section_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "section_icon",
        "section_title"
      ]
    },
    "section_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/gear.svg"
      },
      "children": []
    },
    "section_title": {
      "type": "Text",
      "props": {
        "text": "Address Reservation and dhcpcd.conf Setup",
        "variant": "h2"
      },
      "children": []
    },
    "router_card": {
      "type": "Card",
      "props": {},
      "children": [
        "router_title",
        "router_steps_list"
      ]
    },
    "router_title": {
      "type": "Text",
      "props": {
        "text": "1. Router Web Interface (Address Reservation)",
        "variant": "h3"
      },
      "children": []
    },
    "router_steps_list": {
      "type": "List",
      "props": {},
      "children": [
        "router_step_1",
        "router_step_2",
        "router_step_3",
        "router_step_4",
        "router_step_5",
        "router_step_6"
      ]
    },
    "router_step_1": {
      "type": "Text",
      "props": {
        "text": "Log into your TP-Link router at http://tplinkwifi.net (default user/pass: admin/admin)."
      },
      "children": []
    },
    "router_step_2": {
      "type": "Text",
      "props": {
        "text": "Go to Advanced > Network > DHCP Server."
      },
      "children": []
    },
    "router_step_3": {
      "type": "Text",
      "props": {
        "text": "Scroll down to the Address Reservation section and click Add."
      },
      "children": []
    },
    "router_step_4": {
      "type": "Text",
      "props": {
        "text": "Enter the MAC Address: AA:BB:CC:DD:EE:FF."
      },
      "children": []
    },
    "router_step_5": {
      "type": "Text",
      "props": {
        "text": "Enter the Reserved IP Address: 192.168.1.50."
      },
      "children": []
    },
    "router_step_6": {
      "type": "Text",
      "props": {
        "text": "Click Save and restart the router to apply."
      },
      "children": []
    },
    "pi_config_card": {
      "type": "Card",
      "props": {},
      "children": [
        "pi_config_title",
        "pi_step_1_text",
        "pi_step_1_command",
        "pi_step_2_text",
        "pi_step_2_code",
        "pi_step_3_text",
        "pi_step_4_text",
        "pi_step_4_command"
      ]
    },
    "pi_config_title": {
      "type": "Text",
      "props": {
        "text": "2. Raspberry Pi Configuration (dhcpcd.conf)",
        "variant": "h3"
      },
      "children": []
    },
    "pi_step_1_text": {
      "type": "Text",
      "props": {
        "text": "Open a terminal on your Pi and type:"
      },
      "children": []
    },
    "pi_step_1_command": {
      "type": "ConsoleLog",
      "props": {
        "code": "sudo nano /etc/dhcpcd.conf",
        "language": "console"
      },
      "children": []
    },
    "pi_step_2_text": {
      "type": "Text",
      "props": {
        "text": "Scroll to the bottom and add the following lines:"
      },
      "children": []
    },
    "pi_step_2_code": {
      "type": "ConsoleLog",
      "props": {
        "code": "interface eth0\nstatic ip_address=192.168.1.50/24\nstatic routers=192.168.1.1\nstatic domain_name_servers=192.168.1.1 8.8.8.8",
        "language": "console"
      },
      "children": []
    },
    "pi_step_3_text": {
      "type": "Text",
      "props": {
        "text": "Press Ctrl + O, then Enter to save, and Ctrl + X to exit."
      },
      "children": []
    },
    "pi_step_4_text": {
      "type": "Text",
      "props": {
        "text": "Restart the Pi with:"
      },
      "children": []
    },
    "pi_step_4_command": {
      "type": "ConsoleLog",
      "props": {
        "code": "sudo reboot",
        "language": "console"
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack_buttons": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "rpi_docs_button",
        "tplink_support_button"
      ]
    },
    "rpi_docs_button": {
      "type": "Button",
      "props": {
        "label": "RPi OS Docs"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.raspberrypi.com/documentation/computers/configuration.html"
          }
        }
      },
      "children": []
    },
    "tplink_support_button": {
      "type": "Button",
      "props": {
        "label": "TP-Link Support"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tp-link.com/us/support/"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack_buttons": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "rpi_networking_button",
        "tplink_dhcp_faq_button"
      ]
    },
    "rpi_networking_button": {
      "type": "Button",
      "props": {
        "label": "Raspberry Pi Networking"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.raspberrypi.com/documentation/computers/remote-access.html#ip-address"
          }
        }
      },
      "children": []
    },
    "tplink_dhcp_faq_button": {
      "type": "Button",
      "props": {
        "label": "TP-Link DHCP FAQ"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tp-link.com/us/support/faq/182/"
          }
        }
      },
      "children": []
    }
  }
}
